/**
 * Labelled utterances for the language-detection eval (PLN-261012 SG-53, NFR).
 *
 * Written by hand as realistic Hotel Admin partner-support questions — the
 * traffic Go2Joy's widget will actually see — not scraped, and not generated by
 * the detector's own rules. The one derived bucket is `vi-ascii`: it is the
 * `vi` bucket with the tone marks stripped, which is exactly how many people
 * type Vietnamese on a phone (no diacritics), and what the detector read as
 * English before the ASCII heuristic.
 *
 * `expect` is what a correct detector should answer for that message ON ITS OWN:
 * a language code, or `null` = "not evidence of anything" (short acknowledgement,
 * number, emoji). `limit` marks an utterance the range-based approach cannot
 * settle by design — still listed and still reported, but excluded from the
 * pass threshold so the number stays honest about what the detector claims.
 */

export type CorpusLabel = 'VI' | 'EN' | 'KO' | 'JA' | 'ZH' | 'ES' | null;

export interface CorpusItem {
  text: string;
  expect: CorpusLabel;
  /** Bucket for the per-bucket report. */
  bucket: string;
  /** Why a range detector cannot be expected to get this one (excluded from the threshold). */
  limit?: string;
}

/** Remove Vietnamese tone marks and đ — how unaccented phone typing looks. */
export function stripVietnamese(text: string): string {
  return text
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D');
}

